ode":null,"source_key":"gmap:ChIJufVxTCzboDERFPPiWPJ0y9U","source_url":"https://www.google.com/maps/search/?api=1&query=C%E1%BB%ADa%20h%C3%A0ng%20V%C4%83n%20ph%C3%B2ng%20ph%E1%BA%A9m%20-%20M%E1%BB%B9%20ph%E1%BA%A9m%20L%E1%BA%AFm%20Huy%E1%BB%87n%20G%C3%B2%20Quao&query_place_id=ChIJufVxTCzboDERFPPiWPJ0y9U","verification_note":"Maps tên có VPP và mỹ phẩm, loại Novelty store; cần xác minh có mặt hàng VPP thực tế"},{"province":"Kiên Giang","district":"Thành phố Hà Tiên","name":"Cửa hàng Văn phòng phẩm Thanh Bình","address_line":"07 Mạc Thiên Tích, phường Đông Hồ cũ, TP Hà Tiên, Kiên Giang","category":"van_phong_pham","phone":"02973701661","tax_code":"1701431743","source_key":"gmap:ChIJF5QsTxraCTERqHtSNZYAQ3Q","source_url":"https://www.google.com/maps/search/?api=1&query=C%E1%BB%ADa%20h%C3%A0ng%20V%C4%83n%20ph%C3%B2ng%20ph%E1%BA%A9m%20Thanh%20B%C3%ACnh%20Th%C3%A0nh%20ph%E1%BB%91%20H%C3%A0%20Ti%C3%AAn&query_place_id=ChIJF5QsTxraCTERqHtSNZYAQ3Q","verification_note":"Maps có cửa hàng và điện thoại; hồ sơ thuế https://thuvienphapluat.vn/ma-so-thue/van-phong-pham-thanh-binh-mst-1701431743.html ghi ngành chính bán lẻ sách/VPP cùng địa chỉ; chưa xác minh hoạt động 2026"},{"province":"Kiên Giang","district":"Thành phố Hà Tiên","name":"Tiệm Photocopy, Văn phòng phẩm Xà Xía","address_line":"465 Quốc lộ 80, xã Xà Xía cũ, TP Hà Tiên, Kiên Giang","category":"van_phong_pham","phone":"0832099449","tax_code":null,"source_key":"gmap:ChIJHYUhbADRCTER_WgREgPHUZw","source_url":"https://www.google.com/maps/search/?api=1&query=Ti%E1%BB%87m%20Photocopy%2C%20V%C4%83n%20ph%C3%B2ng%20ph%E1%BA%A9m%20X%C3%A0%20X%C3%ADa%20Th%C3%A0nh%20ph%E1%BB%91%20H%C3%A0%20Ti%C3%AAn&query_place_id=ChIJHYUhbADRCTER_WgREgPHUZw","verification_note":"Maps tên tiệm photo & VPP, phân loại Wholesaler; chưa xác nhận bán lẻ học phẩm"},{"province":"Sóc Trăng","district":"Huyện Mỹ Tú","name":"Cửa hàng Văn phòng phẩm Gia Linh","address_line":"Đường Hùng Vương, TT Huỳnh Hữu Nghĩa cũ, huyện Mỹ Tú, Sóc Trăng","category":"van_phong_pham","phone":"02993871436","tax_code":null,"source_key":"vietbiz:gialinh:hungvuong-huynhhuunghia","source_url":"https://www.viet-biz.com/c%E1%BB%ADa-h%C3%A0ng-v%C4%83n-ph%C3%B2ng-ph%E1%BA%A9m-gia-linh-0299-3871-436","verification_note":"Viet-Biz tên cửa hàng VPP, địa chỉ và số điện thoại, danh mục Novelty store; không phải Tạp hóa Bảy Tỷ đã nhập"},{"province":"Đồng Tháp","district":"Huyện Hồng Ngự","name":"Văn phòng phẩm Lê Ngô","address_line":"R68R+8VM, khu Thường Phước cũ, huyện Hồng Ngự, Đồng Tháp","category":"van_phong_pham","phone":"0902282618","tax_code":null,"source_key":"gmap:ChIJBdiBGjYwCjERk2cvXxY-wv0","source_url":"https://www.google.com/maps/search/?api=1&query=V%C4%83n%20ph%C3%B2ng%20ph%E1%BA%A9m%20L%C3%AA%20Ng%C3%B4%20Huy%E1%BB%87n%20H%E1%BB%93ng%20Ng%E1%BB%B1&query_place_id=ChIJBdiBGjYwCjERk2cvXxY-wv0","verification_note":"Maps Office supply store, có phản hồi mua đồ học tập; một review nói nhà sách chuyển đi, cần gọi kiểm địa điểm thật trước khi Sales ghé"}]'::jsonb) x(
  province text,district text,name text,address_line text,category text,phone text,tax_code text,
  source_key text,source_url text,verification_note text)
), ins AS (
 INSERT INTO public.field_prospects (
  id,area_visit_id,owner_sub,name,address_line,province,district,category,phone,tax_code,note,status,
  source_kind,research_source_key,research_source_url,research_batch
 )
 SELECT (substr(s.dg,1,8)||'-'||substr(s.dg,9,4)||'-5'||substr(s.dg,14,3)||'-8'||substr(s.dg,18,3)||'-'||substr(s.dg,21,12))::uuid,
  NULL,'ef943de4-18f7-49ef-8340-eefb18855534',
  s.name,s.address_line,s.province,s.district,s.category,s.phone,s.tax_code,
  'Vòng 2 online 21/11/2026; CHƯA GHÉ; GPS và sản phẩm bán thực tế chưa xác minh. '||s.verification_note||' Nguồn: '||s.source_url,
  'new','manual',s.source_key,s.source_url,'2026-11-21-old13-round02-p0p1-155'
 FROM src s
 WHERE (s.province,s.district) IN (
  ('Kiên Giang','Huyện Kiên Hải'),('An Giang','Thị xã Tịnh Biên'),('Kiên Giang','Huyện Gò Quao'),
  ('Kiên Giang','Thành phố Hà Tiên'),('Sóc Trăng','Huyện Mỹ Tú'),('Đồng Tháp','Huyện Hồng Ngự'))
  AND s.source_url LIKE 'https://%'
  AND NOT EXISTS (SELECT 1 FROM public.customers c
   WHERE (c.province=s.province AND c.district=s.district AND lower(trim(c.name))=lower(trim(s.name)))
    OR (s.phone IS NOT NULL AND c.phone IS NOT NULL AND regexp_replace(c.phone,'[^0-9]','','g')=regexp_replace(s.phone,'[^0-9]','','g')))
  AND NOT EXISTS (SELECT 1 FROM public.field_prospects p
   WHERE p.research_source_key=s.source_key
    OR (p.province=s.province AND p.district=s.district AND lower(trim(p.name))=lower(trim(s.name)))
    OR (s.phone IS NOT NULL AND p.phone IS NOT NULL AND regexp_replace(p.phone,'[^0-9]','','g')=regexp_replace(s.phone,'[^0-9]','','g'))
    OR (s.tax_code IS NOT NULL AND p.tax_code=s.tax_code))
 ON CONFLICT (research_source_key) WHERE research_source_key IS NOT NULL DO NOTHING
 RETURNING province,district,name,category
)
SELECT province,district,name,category FROM ins ORDER BY province,district,name;
